#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<int> sums_left, sums_right;
    int mid = n / 2;

    function<void(int, long long)> generate_left = [&](int i, long long total) {
        if (i == mid) {
            sums_left.push_back(total % m);
        } else {
            generate_left(i + 1, total + a[i]);
            generate_left(i + 1, total);
        }
    };

    function<void(int, long long)> generate_right = [&](int i, long long total) {
        if (i == n) {
            sums_right.push_back(total % m);
        } else {
            generate_right(i + 1, total + a[i]);
            generate_right(i + 1, total);
        }
    };

    generate_left(0, 0);
    generate_right(mid, 0);

    int max_found = 0;
    int len_right = (int)sums_right.size();

    // Remove duplicates and sort sums_left
    set<int> sums_left_set(sums_left.begin(), sums_left.end());
    vector<int> sums_left_unique(sums_left_set.begin(), sums_left_set.end());

    for (int i : sums_right) {
        int j = (int)(std::lower_bound(sums_left_unique.begin(), sums_left_unique.end(), m - i) - sums_left_unique.begin());
        if (j > 0) {
            int candidate = sums_left_unique[j - 1] + i;
            if (candidate > max_found) {
                max_found = candidate;
            }
        }
    }

    cout << max_found << "\n";

    return 0;
}
